var markoutTypes = typeof(Markout.Markout)?.Assembly?.GetTypes()
    .Where(t => t.Namespace?.StartsWith("Markout") == true)
    .Where(t => !t.IsNested && t.IsPublic)
    .OrderBy(t => t.Name)
    .ToList() ?? new();

